    switch (state) {
      case OptionState.idle:
        return AppOptionStyle(bg: c.surface, border: c.border, badgeBg: c.surfaceMuted, badgeText: c.textMuted);
      case OptionState.selected:
        return AppOptionStyle(bg: c.primarySoft, border: c.primary, badgeBg: c.primary, badgeText: c.onPrimary);
      case OptionState.correct:
        return AppOptionStyle(bg: c.successSoft, border: c.success, badgeBg: c.success, badgeText: c.onPrimary);
      case OptionState.wrong:
        return AppOptionStyle(bg: c.dangerSoft, border: c.danger, badgeBg: c.danger, badgeText: c.onPrimary);
      case OptionState.missed:
        return AppOptionStyle(bg: c.surface, border: c.success, badgeBg: c.successSoft, badgeText: c.success);
    }
  }

  @override
  AppTokens copyWith({AppColors? colors}) => AppTokens(colors: colors ?? this.colors);

  @override
